import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Extract text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const text = textItem?.text ?? 'Features 2';
  const fontSize = textItem?.typography?.fontSize ?? 39;

  // Colors from spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new THREE.Group();

  // Create backdrop plane (engineered gradient surface)
  const backdropGeo = new THREE.PlaneGeometry(2.5, 1.2);

  // Gradient shader: surface (#0b0b10) to paper (#e8ecf2) vertical
  const gradNode = mix(
    color(colors.surface),
    color(colors.paper),
    mix(0, 0.08, uv().y)
  );

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradNode,
    side: THREE.FrontSide,
    transparent: true,
    opacity: 0.95
  });

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.02;
  group.add(backdrop);

  // Load and apply decorative image as overlay plane
  const imageGeo = new THREE.PlaneGeometry(2.2, 1.0);
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.25,
    side: THREE.FrontSide
  });

  const imageMesh = new THREE.Mesh(imageGeo, imageMat);
  imageMesh.position.z = -0.01;
  group.add(imageMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMat.map = texture;
      imageMat.needsUpdate = true;
    }).catch(() => {
      // Fallback: keep the plane visible with gradient only
    });
  }

  // Render headline text
  const textMesh = ctx.fontAtlas.createText(text, {
    fontSize: fontSize / 16,
    color: colors.ink,
    align: 'center'
  });
  textMesh.position.set(0, 0.15, 0.01);
  group.add(textMesh);

  // Apply scene position
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }

  // Apply rotation and scale
  if (config.sceneRotation) {
    group.rotation.copy(config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // Event handlers
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    backdropGeo.dispose();
    backdropMat.dispose();
    imageGeo.dispose();
    imageMat.dispose();
    if (imageMat.map) imageMat.map.dispose();
    textMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
